package com.nyayaconnect.document;
import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Repository;import java.util.*;
@Repository public class JdbcDocumentDao implements DocumentDao {private final JdbcTemplate db;public JdbcDocumentDao(JdbcTemplate db){this.db=db;}
 public UUID insert(UUID caseId,String original,String key,String mime,long size,String sha,UUID user){UUID id=UUID.randomUUID();db.update("insert into documents(id,case_id,original_name,storage_key,mime_type,size_bytes,sha256,uploaded_by) values(?,?,?,?,?,?,?,?)",id.toString(),caseId.toString(),original,key,mime,size,sha,user.toString());db.update("insert into document_versions(id,document_id,version_no,storage_key,sha256,size_bytes,mime_type,uploaded_by,change_reason) values(?,?,?,?,?,?,?,?,?)",UUID.randomUUID().toString(),id.toString(),1,key,sha,size,mime,user.toString(),"Initial upload");return id;}
 public Optional<DocumentRecord> find(UUID id){return db.query("select id,case_id,original_name,storage_key,mime_type,size_bytes from documents where id=?",(rs,rowNum)->new DocumentRecord(UUID.fromString(rs.getString("id")),UUID.fromString(rs.getString("case_id")),rs.getString("original_name"),rs.getString("storage_key"),rs.getString("mime_type"),rs.getLong("size_bytes")),id.toString()).stream().findFirst();}
 public void accessLog(UUID id,UUID user,String action,String ip){db.update("insert into document_access_logs(id,document_id,user_id,action,ip_address) values(?,?,?,?,?)",UUID.randomUUID().toString(),id.toString(),user.toString(),action,ip);}}
